def seconds_until_allowed(headers, now_epoch):
    """0 if budget remains, else seconds until the window resets."""
    if int(headers.get("x-ratelimit-remaining", "1")) > 0:
        return 0.0
    return max(0.0, int(headers["x-ratelimit-reset"]) - now_epoch)

